import './project-enhance.mjs?v=0.7.0';
import {modules} from './engineering-content.mjs';

const page=document.getElementById('page-engineering');
const oldDiagram=page.querySelector('.system-drawing svg');
page.dataset.engineeringDesign='silver';
const extra={
  aero:{code:'AeroDyn',intro:'风经过叶片，形成气动力与气动转矩。',input:'风场 / 叶片几何 / 结构运动',inputNote:'本项目输入轮毂高度稳定风速；叶片几何与气动参数沿用固定参考模型。',effect:'气动载荷',effectNote:'叶片相对来流和结构运动共同影响气动力，载荷再传递给结构动力学模块。',watchNote:'转子转速与发电功率需结合控制器和结构响应共同解释。',question:'为什么风速相同，短时功率也会不同？',answer:'初始转速、桨距、平台运动和启动过程都可能影响时序。比较工况时应统一结构与控制器、计算时长和分析窗口，不能只看单一风速。',compare:[['环境输入','稳定风速 / m/s'],['载荷传递','叶片 → 转子与塔架'],['响应观察','RotSpeed / GenPwr']]},
  hydro:{code:'HydroDyn',intro:'波浪作用于浮式基础，与平台运动耦合。',input:'波浪参数 / 平台运动',inputNote:'规则波使用 H、T；JONSWAP 使用 Hs、Tp 和随机种子。SeaState 提供海况。',effect:'水动力载荷',effectNote:'水动力载荷与平台运动相互影响，并与结构、系泊作用一起参与耦合求解。',watchNote:'查看波面高程、平台纵摇和纵荡时序，结合分析窗口复核响应。',question:'规则波的 H、T 与不规则波的 Hs、Tp 有什么区别？',answer:'H、T 分别描述规则波的波高和周期。Hs 是不规则海况的显著波高，Tp 是谱峰周期；相同数值不代表相同波浪时序。不规则波比较还需记录随机种子。',compare:[['海况输入','H / T，或 Hs / Tp / seed'],['载荷传递','海况 → 浮式基础'],['响应观察','Wave1Elev / PtfmPitch / PtfmSurge']]},
  structure:{code:'ElastoDyn',intro:'连接各类载荷，求解结构运动与振动。',input:'耦合载荷 / 质量与刚度',inputNote:'结构、质量、刚度和初始条件采用固定官方参考输入，与其他模块交换载荷和运动量。',effect:'结构动力学响应',effectNote:'气动、水动力、系泊与控制作用共同影响转子、塔架和平台的运动。',watchNote:'联系转子转速、平台纵摇与塔底弯矩，观察载荷和运动如何共同变化。',question:'平台纵摇与纵荡分别描述什么？',answer:'纵摇 PtfmPitch 是平台绕对应横向轴的转动，纵荡 PtfmSurge 是沿对应纵向轴的平移。解释数值前应核对参考模型的坐标定义与输出单位；两者不能直接相加或比较大小。',compare:[['结构输入','质量 / 刚度 / 初始条件'],['耦合信息','载荷 ↔ 运动'],['响应观察','RotSpeed / PtfmPitch / TwrBsMyt']]},
  mooring:{code:'MoorDyn',intro:'系泊连接平台与海床，提供恢复作用。',input:'平台运动 / 系泊线与锚点',inputNote:'系泊线、连接点和锚点沿用参考配置；平台位置和运动会改变系泊状态。',effect:'系泊恢复作用',effectNote:'系泊作用反过来影响平台的位移和转动，形成双向耦合。',watchNote:'本项目关注平台纵荡与纵摇；当前结果页没有单独展示各条系泊线张力。',question:'为什么不能用平台位移直接判断系泊是否安全？',answer:'平台运动与系泊张力有关，但并不等价。安全判断还需要各条线的张力、材料强度、疲劳及极限工况等资料；当前原型的短时平台响应不能代替这些检查。',compare:[['固定配置','线型 / 导缆点 / 海床锚点'],['耦合信息','平台运动 ↔ 系泊作用'],['响应观察','PtfmSurge / PtfmPitch']]},
  control:{code:'ServoDyn',intro:'控制器调节机组状态，影响转速与功率。',input:'转速与桨距 / 控制状态',inputNote:'ServoDyn 与参考控制器交换状态和控制动作，本项目固定采用 OC3Hywind 控制器。',effect:'控制与发电响应',effectNote:'控制动作参与动力学计算，不能把风速直接换算成某个固定的短时功率。',watchNote:'将发电功率与转子转速放在同一时间窗口观察，并检查启动过渡。',question:'功率的短时均值能代表年发电量吗？',answer:'不能。短时均值只描述所选工况和分析窗口。年发电量还需要长期风资源分布、可利用率、损耗和运行条件等资料，当前原型不据此外推。',compare:[['控制配置','参考控制器 / 固定初始条件'],['耦合信息','机组状态 ↔ 控制动作'],['响应观察','GenPwr / RotSpeed']]}
};
const icons={input:'<path d="M3 8q4-5 8 0t8 0M3 13q4-5 8 0t8 0M3 18q4-5 8 0t8 0"/>',effect:'<path d="M5 17 18 4M7 4h11v11"/>',watch:'<path d="M4 3v17h17M6 15l5-6 4 3 6-7"/>'};
function icon(key){return `<svg viewBox="0 0 24 24" aria-hidden="true">${icons[key]}</svg>`;}
page.replaceChildren();
page.innerHTML=`<header class="atlas-intro"><div><span class="kicker">02 / ENGINEERING NOTES</span><h1 class="visually-hidden">工程原理</h1><p>从输入载荷，到运动响应。</p></div><button class="atlas-explore" data-jump="principle-deep">向下探索原理 <span>↓</span></button></header>
<section class="atlas-hero" aria-label="工程原理交互图解">
  <div class="atlas-visual"><img src="./assets/engineering-silver-scene.png" alt="银白色半潜式海上风机、海面及水下系泊结构原理示意" fetchpriority="high">
    <svg class="atlas-forces" viewBox="0 0 720 800" aria-hidden="true"><defs><marker id="atlas-arrow-cyan" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="m0 0 10 5-10 5 3-5Z" fill="#49bfd5"/></marker><marker id="atlas-arrow-gold" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="m0 0 10 5-10 5 3-5Z" fill="#dfb45b"/></marker></defs><g data-load="aero" class="force-wind"><path d="M100 158H285M110 183H285M100 208H285" marker-end="url(#atlas-arrow-cyan)"/></g><g data-load="hydro" class="force-waves"><path d="M0 433q15-14 30 0t30 0t30 0t30 0t30 0h35M0 455q15-14 30 0t30 0t30 0t30 0t30 0h35M0 477q15-14 30 0t30 0t30 0t30 0t30 0h35" marker-end="url(#atlas-arrow-cyan)"/></g><g data-load="mooring" class="force-mooring"><path d="M565 713Q500 674 470 606M586 715Q526 666 502 608" marker-end="url(#atlas-arrow-gold)"/></g><g data-load="structure" class="force-structure"><path d="M410 310V470M400 318l10-8 10 8M400 462l10 8 10-8"/><path d="M295 552H520" stroke-dasharray="4 5"/></g><g data-load="control" class="force-control"><circle cx="390" cy="268" r="30"/><path d="M370 268h40M390 248v40"/></g></svg>
    <button class="atlas-callout callout-aero" data-topic="aero"><b>风载荷</b><span>来自 AeroDyn</span></button><button class="atlas-callout callout-hydro" data-topic="hydro"><b>波浪载荷</b><span>来自 HydroDyn</span></button><button class="atlas-callout callout-structure" data-topic="structure"><b>浮式平台运动</b><span>载荷与结构相互影响</span></button><button class="atlas-callout callout-mooring" data-topic="mooring"><b>系泊恢复作用</b><span>来自 MoorDyn</span></button><button class="atlas-callout callout-control" data-topic="control"><b>机舱与控制</b><span>来自 ServoDyn</span></button><small class="atlas-visual-note">原理示意 · 非仿真结果</small>
  </div>
  <nav class="atlas-tabs" aria-label="工程原理模块">${modules.map((m,i)=>`<button data-topic="${m.id}" aria-pressed="false"><span>0${i+1}</span>${m.name}</button>`).join('')}</nav>
  <article class="atlas-copy" id="principle-overview"><span class="kicker" id="atlas-label"></span><h2 id="atlas-title"></h2><span class="atlas-code" id="atlas-code"></span><p class="atlas-description" id="atlas-description"></p><dl class="atlas-facts">${['input','effect','watch'].map((key,i)=>`<div><span class="fact-icon">${icon(key)}</span><div><dt><b>${['输入','作用','关注输出'][i]}：</b><span id="atlas-${key}"></span></dt><dd id="atlas-${key}-note"></dd></div></div>`).join('')}</dl><div class="atlas-actions"><a class="atlas-primary" id="atlas-source" target="_blank" rel="noopener">官方文档 <span>↗</span></a><button class="atlas-secondary" data-page="configure">配置工况 <span>→</span></button></div><p class="atlas-hint">点击上方模块或图中标注，沿着载荷与响应探索。</p></article>
</section>
<section class="atlas-coupling" aria-labelledby="coupling-title"><div class="atlas-section-caption"><h2 id="coupling-title">多物理场耦合关系 <span>/ OPENFAST COUPLING</span></h2><button data-jump="principle-deep">继续了解 ↓</button></div><div class="coupling-nodes">${[modules[0],modules[1],null,modules[2],modules[3],modules[4]].map(m=>m?`<button class="coupling-node" data-topic="${m.id}" aria-pressed="false"><strong>${extra[m.id].code}</strong><span>${m.name}</span><small>${{aero:'风与转子气动作用',hydro:'波浪与平台耦合',structure:'风机与平台结构响应',mooring:'系泊线与平台耦合',control:'控制动作与机组状态'}[m.id]}</small></button>`:'<button class="coupling-core" data-jump="principle-deep"><strong>OpenFAST</strong><span>多物理场耦合</span><small>交换载荷、运动与控制量</small></button>').join('')}</div><p class="coupling-note">各模块通过主求解过程交换信息；这里展示关联关系，不表示串行执行顺序。</p></section>
<section class="atlas-deep" id="principle-deep" aria-labelledby="deep-title"><div class="deep-heading"><div><span class="kicker">READ THE SYSTEM / 继续向下探索</span><h2 id="deep-title">把原理，连到一次真实计算。</h2></div><button class="atlas-back" data-jump="principle-overview">返回当前模块 ↑</button></div><div class="atlas-reading"><article><span>01 / ENVIRONMENT</span><h3>先定义环境输入</h3><p>选择稳定风、规则波或 JONSWAP 波浪，保留波高、周期、随机种子与求解设置。</p></article><article><span>02 / COUPLING</span><h3>载荷与运动双向交换</h3><p>气动、水动力、系泊、结构和控制共同参与计算。平台运动会改变受载，载荷也会反过来影响运动。</p></article><article><span>03 / RESPONSE</span><h3>再观察输出时序</h3><p>核查日志、分析起点和输出单位。在一致的窗口内比较功率、转速及平台响应。</p></article></div>
<div class="atlas-detail-grid"><article class="atlas-module-reading"><span class="kicker">CURRENT MODULE / 当前模块</span><h3 id="atlas-reading-title"></h3><p id="atlas-reading-text"></p><dl id="atlas-reading-specs"></dl><p class="atlas-boundary" id="atlas-boundary"></p></article><div class="atlas-accordions"><details><summary id="atlas-question"></summary><p id="atlas-answer"></p></details><details><summary>怎么看输出曲线与分析窗口？</summary><p>先观察完整时序，再结合启动过程选择分析起点。统一分析窗口后再比较工况，短时峰值和均值都只描述当前设置。</p><div class="channel-guide"><span><b>PtfmPitch</b>平台纵摇</span><span><b>PtfmSurge</b>平台纵荡</span><span><b>GenPwr</b>发电机功率</span></div></details><details><summary>这张图和真实仿真是什么关系？</summary><p>图中的海面、结构外观和载荷箭头用于讲解，没有播放求解结果。结构、控制器与系泊配置以运行输入为准；计算完成后到结果分析页查看真实时序。</p><button class="atlas-inline" data-page="model">查看可交互三维结构 ↗</button></details></div></div>
<details class="atlas-line-drawing"><summary>展开系统结构线图 <span>↘</span></summary><div class="atlas-diagram-slot"></div><p>系统关系示意，不用于工程测量。</p></details><div class="atlas-end"><p>准备好把原理带进工况比较了吗？<span>从单一变量开始，保留每一次计算依据。</span></p><button class="atlas-primary" data-page="configure">开始配置工况 →</button></div></section>`;
if(oldDiagram)page.querySelector('.atlas-diagram-slot').append(oldDiagram);
const $=id=>document.getElementById(id);
function select(id){const m=modules.find(m=>m.id===id),e=extra[id];if(!m||!e)return;page.dataset.topic=id;
  page.querySelectorAll('button[data-topic]').forEach(b=>{const active=b.dataset.topic===id;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});
  $('atlas-label').textContent='0'+(modules.indexOf(m)+1)+' / '+e.code.toUpperCase();$('atlas-title').textContent=m.name;$('atlas-code').textContent=e.code;$('atlas-description').textContent=e.intro;
  for(const [key,value] of Object.entries({input:e.input,'input-note':e.inputNote,effect:e.effect,'effect-note':e.effectNote,watch:m.watch,'watch-note':e.watchNote}))$('atlas-'+key).textContent=value;
  $('atlas-source').href=m.link;$('atlas-reading-title').textContent=m.title;$('atlas-reading-text').textContent=m.text;$('atlas-boundary').textContent=m.limit;$('atlas-question').textContent=e.question;$('atlas-answer').textContent=e.answer;
  $('atlas-reading-specs').replaceChildren(...e.compare.map(([name,value])=>{const row=document.createElement('div'),dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=name;dd.textContent=value;row.append(dt,dd);return row;}));
  page.querySelectorAll('[data-load]').forEach(g=>g.classList.toggle('active',g.dataset.load===id));
}
function jump(id){document.getElementById(id)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth',block:'start'});}
page.addEventListener('click',event=>{const topic=event.target.closest('button[data-topic]');if(topic)select(topic.dataset.topic);const b=event.target.closest('[data-jump]');if(b)jump(b.dataset.jump);});
page.querySelector('.atlas-tabs').addEventListener('keydown',event=>{const current=event.target.closest('[data-topic]');if(event.ctrlKey||event.metaKey||event.altKey||!current||!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();const buttons=[...page.querySelectorAll('.atlas-tabs button')];const at=buttons.indexOf(current);const next=event.key==='Home'?0:event.key==='End'?buttons.length-1:(at+(event.key==='ArrowRight'?1:-1)+buttons.length)%buttons.length;buttons[next].focus();select(buttons[next].dataset.topic);});
select('hydro');
const brandImage=document.querySelector('.brand-lockup img'),originalBrand=brandImage.getAttribute('src');
function brand(){brandImage.setAttribute('src',originalBrand);}
new MutationObserver(brand).observe(document.body,{attributes:true,attributeFilter:['data-page']});brand();
